<div class="card"><div class="card-header"><h5 class="mb-0">Filter Tagihan Per Kelas</h5></div><div class="card-body"><div class="row g-2"><div class="col-md-3"><select id="periode" class="form-select"><option value="">Tahun Ajaran</option><?php foreach($periode as $p): ?><option value="<?= $p['id'] ?>"><?= html_escape($p['periode']) ?></option><?php endforeach ?></select></div><div class="col-md-3"><select id="kelas" class="form-select"><option value="">Semua Kelas</option><?php foreach($kelas as $k): ?><option value="<?= $k['id'] ?>" data-period="<?= $k['id_periode'] ?>"><?= html_escape($k['nama_kelas'].' - '.$k['semester']) ?></option><?php endforeach ?></select></div><div class="col-md-3"><select id="bulan" class="form-select"><option value="">Sampai Semua Bulan</option><?php for($i=1;$i<=12;$i++): ?><option value="<?= $i ?>">Sampai <?= nama_bulan($i) ?></option><?php endfor ?></select></div><div class="col-md-3 d-grid"><button id="tampil" class="btn btn-primary">Tampilkan</button></div></div></div></div>
<div class="card"><div class="card-header d-flex justify-content-between"><h5 class="mb-0">Ringkasan Siswa</h5><div><button onclick="window.print()" class="btn btn-secondary no-print">Cetak</button></div></div><div class="card-body"><div class="table-responsive"><table class="table table-hover align-middle"><thead><tr><th>Siswa</th><th>Kelas</th><th class="text-end">Total Wajib</th><th class="text-end">Dibayar</th><th class="text-end">Tunggakan</th><th>Status</th><th>Aksi</th></tr></thead><tbody id="data"><tr><td colspan="7" class="empty-state">Pilih filter.</td></tr></tbody></table></div></div></div>
<div class="modal fade" id="modalDetail"><div class="modal-dialog modal-xl"><div class="modal-content"><div class="modal-header"><h5 class="modal-title">Detail Tagihan Siswa</h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body" id="detail"></div></div></div></div>
<script>$(function(){const money=n=>'Rp'+Number(n||0).toLocaleString('id-ID');function load(){$.post('<?= base_url('tagihan_per_kelas/result') ?>',{id_periode:$('#periode').val(),id_kelas_setting:$('#kelas').val(),sampai_bulan:$('#bulan').val()},r=>{$('#data').html(r.length?r.map(x=>`<tr><td><strong>${escapeHtml(x.nama_siswa)}</strong><br><small>${escapeHtml(x.nis)}</small></td><td>${escapeHtml(x.nama_kelas)}</td><td class="text-end">${money(x.total_wajib)}</td><td class="text-end">${money(x.dibayar)}</td><td class="text-end fw-semibold text-${Number(x.tunggakan)>0?'danger':'success'}">${money(x.tunggakan)}</td><td><span class="badge bg-${x.status==='Lunas'?'success':'warning'}-subtle text-${x.status==='Lunas'?'success':'warning'}">${x.status}</span></td><td><button class="btn btn-sm btn-primary detail" data-id="${x.id_siswa}">Detail</button></td></tr>`).join(''):'<tr><td colspan="7" class="empty-state">Tidak ada data.</td></tr>')},'json').fail(ajaxError)}$('#tampil').click(load);$('#periode').change(function(){let p=this.value;$('#kelas option').each(function(){$(this).toggle(!this.value||!p||String($(this).data('period'))===String(p))});$('#kelas').val('')});$(document).on('click','.detail',function(){$.post('<?= base_url('tagihan_per_kelas/detail') ?>',{id_siswa:$(this).data('id'),id_periode:$('#periode').val()},r=>{$('#detail').html('<div class="table-responsive"><table class="table"><thead><tr><th>Tagihan</th><th>Periode</th><th class="text-end">Nominal</th><th class="text-end">Dibayar</th><th class="text-end">Sisa</th><th>Status</th></tr></thead><tbody>'+r.map(x=>`<tr><td>${escapeHtml(x.nama_tagihan)}</td><td>${escapeHtml((x.nama_bulan||'')+' '+x.tahun)}</td><td class="text-end">${money(x.nominal_tagihan)}</td><td class="text-end">${money(x.nominal_dibayar)}</td><td class="text-end">${money(x.sisa_tagihan)}</td><td>${escapeHtml(x.status_pembayaran)}</td></tr>`).join('')+'</tbody></table></div>');bootstrap.Modal.getOrCreateInstance(document.getElementById('modalDetail')).show()},'json')})});</script>
